"use strict";
/* Generates assets/js/kernel/bundle.generated.js from the kernel source files.

   Run after ANY change to assets/js/kernel/*.js or assets/js/kernel/rulesets/*.js:
     node tools/build-kernel-bundle.js

   Why this exists: every kernel file is a plain CommonJS module — `const { Expr } =
   require("./expr")`, `module.exports = {...}` — verified byte-for-byte by
   tests/verify-kernel*.js and friends under Node's real require(). Node's per-file module
   scope means many files can each declare `const Expr = ...` (via destructuring) with no
   collision. A browser has no such per-file scope: classic <script> tags and importScripts
   calls all evaluate into ONE shared top-level lexical environment for let/const, so loading
   a second kernel file that destructures the same import name throws "Identifier 'Expr' has
   already been declared" — confirmed by actually trying the naive approach (a flat
   require-shim across N importScripts calls) against the real worker-boot test harness.

   The fix is standard CommonJS-in-a-bundle: wrap each file's untouched source in its own
   function scope, so its top-level declarations are local to that function invocation, not
   shared. No kernel source file is modified — this script only reads and wraps them, so the
   files the test suites exercise stay byte-identical to what ships. */

const fs = require("fs");
const path = require("path");

const KERNEL_DIR = path.join(__dirname, "..", "assets", "js", "kernel");
const OUT_FILE = path.join(KERNEL_DIR, "bundle.generated.js");

// Topological order — every require() must already be registered when a file's factory runs.
// Checked directly against each file's own require() lines (see docs/kernel/03_ARCHITECTURE.md
// for the layer picture); not guessed.
const MODULES = [
  "rational", "expr", "parser", "printer", "assumptions", "branch",
  "pattern", "rules", "tree-walk", "collect", "cost", "derivation", "rewrite",
  "rulesets/radicals", "rulesets/inverse-trig", "rulesets/log-exp", "rulesets/trig-identities",
  "rulesets/completing-square", "rulesets/factor", "rulesets/rationalize",
  "rulesets/weierstrass", "rulesets/rationalizing-substitution", "rulesets/algebraic-substitution",
  "rulesets/trig-power-reduction",
  // Phase 3 (polynomial & rational algebra) + Phase 4 (series & limits) foundation slices.
  // Order checked against each file's own require() lines (see docs/kernel/04_BUILD_PHASES.md
  // Phase 3/4 status notes): polynomial before anything that builds on Poly; poly-of-expr
  // needs expr+rational+polynomial (already registered above); factor-rat needs squarefree;
  // rational-integrate needs poly-gcd/factor-rat/partial-fractions/poly-of-expr; taylor needs
  // differentiate; laurent needs taylor+factor-rat+partial-fractions+poly-of-expr; limit needs
  // differentiate+laurent+taylor+assumptions.
  "polynomial", "poly-of-expr", "poly-gcd", "resultant", "squarefree", "factor-rat",
  "partial-fractions", "rational-integrate",
  "differentiate", "taylor", "laurent", "singularity", "convergence", "limit",
  "directed", "bridge",
];

function build() {
  const parts = [];
  parts.push(
    '"use strict";\n' +
    "/* AUTO-GENERATED by tools/build-kernel-bundle.js — do not edit by hand.\n" +
    "   Regenerate with: node tools/build-kernel-bundle.js\n" +
    "   Source: assets/js/kernel/*.js and assets/js/kernel/rulesets/*.js (unmodified below,\n" +
    "   each wrapped in its own function scope — see the generator script for why). */\n" +
    "(function () {\n" +
    "  var __registry = Object.create(null);\n" +
    "  function __require(spec) {\n" +
    '    var name = spec.split("/").pop().replace(/\\.js$/, "");\n' +
    "    if (!(name in __registry)) throw new Error(\"Kernel module not loaded yet: \" + name + \" (requested as \" + spec + \")\");\n" +
    "    return __registry[name];\n" +
    "  }\n"
  );

  for (const name of MODULES) {
    const file = path.join(KERNEL_DIR, name + ".js");
    const source = fs.readFileSync(file, "utf8");
    const shortName = name.split("/").pop();
    parts.push(
      "  __registry[" + JSON.stringify(shortName) + "] = (function (module, exports, require) {\n" +
      source +
      "\n    return module.exports;\n" +
      "  })({ exports: {} }, {}, __require);\n"
    );
  }

  parts.push(
    "  var g = typeof self !== \"undefined\" ? self : (typeof globalThis !== \"undefined\" ? globalThis : this);\n" +
    "  g.KernelBridge = __registry[\"bridge\"] || null;\n" +
    "})();\n"
  );

  return parts.join("\n");
}

module.exports = { build, MODULES, OUT_FILE };

if (require.main === module) {
  const bundle = build();
  fs.writeFileSync(OUT_FILE, bundle);
  console.log("Wrote " + OUT_FILE + " (" + bundle.length + " bytes, " + MODULES.length + " modules)");
}
